function getPayrollDetailPrintDocumentHtml(variant, pagination) {

  if (typeof buildPayrollDetailPrintDocumentHtml !== "function") return null;

  return buildPayrollDetailPrintDocumentHtml(variant, pagination);

}



function exportPayrollDetailPDF(data, variant, pagination) {

  const declaration = data.declarationPresentation;

  const declarationLength = declaration && declaration.primary

    ? String(declaration.primary.renderedText || "").length + String(declaration.english && declaration.english.renderedText || "").length

    : 0;

  if (declarationLength > 1800 && typeof showNotification === "function") {

    showNotification("声明内容较长，将按内容分页以保持至少 7pt 的可读字号", "info");

  }

  const docHtml = getPayrollDetailPrintDocumentHtml(variant, pagination);

  if (!docHtml) {

    if (typeof showNotification === "function") showNotification(T("export.noPrintContent"), "error");

    setPayrollDetailExportStatus("error", "无法生成 PDF：明细内容为空");

    return;

  }

  setPayrollDetailExportStatus("loading", variant === "compact" ? "正在生成精简明细 PDF…" : "正在生成详细明细 PDF…");
  if (typeof showNotification === "function") showNotification(T("export.generatingPdf"), "info");

  loadHtml2CanvasLib(function (h2cReady) {

    loadJsPDFLib(function (jspdfReady) {

      if (h2cReady && jspdfReady) {

        renderPayrollDetailPdfFromPrintTemplate(docHtml, data);

      } else {

        setPayrollDetailExportStatus("error", "PDF 组件加载失败，已打开打印预览");

        openPayrollDetailPrintWindowAndPrint(docHtml, data);

      }

    });

  });

}



function preparePayrollDetailCaptureRoot(root) {

  if (!root) return { width: 0, height: 0 };

  root.querySelectorAll(".payroll-detail-daily-wrap").forEach(function (wrap) {

    wrap.style.overflow = "visible";

    wrap.style.width = "100%";

  });

  root.querySelectorAll(".payroll-detail-daily-table").forEach(function (table) {

    table.style.minWidth = "1080px";

    table.style.width = "max-content";

    table.style.maxWidth = "none";

  });

  const tableWidths = Array.prototype.map.call(

    root.querySelectorAll(".payroll-detail-daily-table"),

    function (table) {

      return table.scrollWidth || table.offsetWidth || 0;

    }

  );

  const widestTable = tableWidths.length ? Math.max.apply(null, tableWidths) : 0;

  const captureWidth = Math.max(root.scrollWidth, root.offsetWidth, widestTable + 48, 1080);

  const captureHeight = Math.max(root.scrollHeight, root.offsetHeight);

  root.style.maxWidth = "none";

  root.style.width = captureWidth + "px";

  return { width: captureWidth, height: captureHeight };

}



function renderPayrollDetailPdfFromPrintTemplate(docHtml, data) {

  const iframe = document.createElement("iframe");

  iframe.setAttribute("aria-hidden", "true");

  iframe.style.cssText = "position:fixed;left:-10000px;top:0;width:1280px;min-height:1600px;border:0;opacity:0;pointer-events:none";

  document.body.appendChild(iframe);



  let finished = false;

  let capturing = false;

  function cleanup() {

    iframe.remove();

  }

  function finishFallback() {

    if (finished) return;

    finished = true;

    cleanup();

    openPayrollDetailPrintWindowAndPrint(docHtml, data);

  }



  function runCapture() {

    if (finished || capturing) return;

    const idoc = iframe.contentDocument;

    const target = idoc && idoc.querySelector(".payroll-detail-print");

    if (!target || !window.html2canvas || !window.jspdf) {

      finishFallback();

      return;

    }

    capturing = true;

    const metrics = preparePayrollDetailCaptureRoot(target);

    const captureWidth = metrics.width || target.scrollWidth || target.offsetWidth;

    const captureHeight = metrics.height || target.scrollHeight || target.offsetHeight;

    window

      .html2canvas(target, {

        scale: 2,

        useCORS: true,

        logging: false,

        backgroundColor: "#ffffff",

        width: captureWidth,

        height: captureHeight,

        windowWidth: captureWidth,

        windowHeight: captureHeight,

      })

      .then(function (canvas) {

        if (finished) return;

        finished = true;

        const imgData = canvas.toDataURL("image/png");

        const pdf = new window.jspdf.jsPDF("p", "mm", "a4");

        const pageW = pdf.internal.pageSize.getWidth();

        const pageH = pdf.internal.pageSize.getHeight();

        const imgW = pageW;

        const imgH = (canvas.height * imgW) / canvas.width;

        let heightLeft = imgH;

        let position = 0;

        pdf.addImage(imgData, "PNG", 0, position, imgW, imgH);

        heightLeft -= pageH;

        while (heightLeft > 0) {

          position = heightLeft - imgH;

          pdf.addPage();

          pdf.addImage(imgData, "PNG", 0, position, imgW, imgH);

          heightLeft -= pageH;

        }

        pdf.save(payrollDetailFileSlug(data, data.exportVariant) + ".pdf");

        cleanup();

        if (typeof showNotification === "function") showNotification(T("export.pdfSuccess"), "success");

        setPayrollDetailExportStatus("success", data.exportVariant === "compact" ? "精简明细 PDF 已导出" : "详细明细 PDF 已导出");

        if (typeof onPayrollDetailExported === "function") onPayrollDetailExported("pdf", data);

      })

      .catch(function () {

        capturing = false;

        setPayrollDetailExportStatus("error", "PDF 生成失败，已打开打印预览");

        finishFallback();

      });

  }



  const idoc = iframe.contentDocument;

  idoc.open();

  idoc.write(docHtml);

  idoc.close();

  iframe.onload = function () {

    setTimeout(runCapture, 500);

  };

  setTimeout(runCapture, 1500);

}



function openPayrollDetailPrintWindowAndPrint(docHtml, data) {

  if (typeof showNotification === "function") showNotification(T("export.printPreview"), "info");

  const iframe = document.createElement("iframe");

  iframe.setAttribute("aria-hidden", "true");

  iframe.style.cssText = "position:fixed;left:-10000px;top:0;width:210mm;height:297mm;border:0;pointer-events:none";

  document.body.appendChild(iframe);

  let printed = false;

  let released = false;

  function releaseFrame() {

    if (released) return;

    released = true;

    setTimeout(function () {

      iframe.remove();

    }, 300);

  }

  function triggerPrint() {

    if (printed) return;

    const frameWindow = iframe.contentWindow;

    if (!frameWindow) {

      setPayrollDetailExportStatus("error", "打印预览生成失败，请重试");

      releaseFrame();

      return;

    }

    printed = true;

    frameWindow.addEventListener("afterprint", releaseFrame);

    try {

      frameWindow.focus();

      frameWindow.print();

    } catch (e) {

      setPayrollDetailExportStatus("error", "打印预览生成失败，请重试");

    }

    setTimeout(releaseFrame, 60000);

  }

  const printDoc = iframe.contentDocument;

  printDoc.open();

  printDoc.write(docHtml);

  printDoc.close();

  iframe.onload = function () {

    setTimeout(triggerPrint, 300);

  };

  setTimeout(triggerPrint, 1200);

  if (typeof showNotification === "function") {

    showNotification(T("export.printOpened"), "success");

  }

  if (typeof onPayrollDetailExported === "function") onPayrollDetailExported("pdf", data);

}



function printPayrollDetail(variant, pagination) {
  const data = getPayrollDetailExportData();
  if (!data) return;
  data.exportVariant = variant === "compact" ? "compact" : "detail";
  data.printPagination = pagination === "paginate" ? "paginate" : "fit-one-page";
  const html = getPayrollDetailPrintDocumentHtml(data.exportVariant, data.printPagination);
  if (html) openPayrollDetailPrintWindowAndPrint(html, data);
}

let payrollEmailExportSnapshot = null;

