  function readStoredTab() {
    try {
      const raw = sessionStorage.getItem(TAB_STORAGE_KEY);
      return raw === "roles" ? "roles" : "employees";
    } catch {
      return "employees";
    }
  }

  function writeStoredTab(tab) {
    try {
      sessionStorage.setItem(TAB_STORAGE_KEY, tab === "roles" ? "roles" : "employees");
    } catch {
      /* ignore */
    }
  }

