    function sortPoolConditionLoadKeys(keys) {
      var preferred = ['role', 'employee', 'area', 'orderType', 'menu', 'revenueType', 'orderTipStatus', 'paymentMethods', 'hours', 'surchargeType', 'tipType', 'containsProduct', 'shift', 'weekdays'];
      return keys.filter(function(k) { return k !== 'employees' && k !== 'employeeRoles'; }).sort(function(a, b) {
        var ia = preferred.indexOf(a);
        var ib = preferred.indexOf(b);
        if (ia === -1) ia = 999;
        if (ib === -1) ib = 999;
        if (ia !== ib) return ia - ib;
        return String(a).localeCompare(String(b));
      });
    }
