    function saveTipsCondition() {
      if (editingDeductTipsCardId) {
        var cardId = editingDeductTipsCardId;
        var condition = Object.assign({}, tipsDrawerRetainedConditions, collectTipsConditions());
        if (!hasContributorScope(condition)) { showNotification('角色和员工必须选择其中一项，并至少选择一个角色或员工', 'error'); return; }
        if (condition.tipType === '__saved_tip_types__') condition.tipTypes = tipsDrawerSavedTipTypes.slice();
        else condition.tipTypes = condition.tipType ? [condition.tipType] : [];
        delete condition.tipType; delete condition.revenueType;
        if ((condition.employee || []).length && (!deductEmployeeShares[cardId] || deductEmployeeShares[cardId].mode !== 'weights')) delete deductEmployeeShares[cardId];
        deductValueConditions[cardId] = condition;
        updateDeductCardConditionDisplay(cardId);
        closeDrawer('tipsDrawer'); showNotification('取值条件已保存'); return;
      }
      if (currentEditingRuleId) {
        var tc = collectTipsConditions();
        normalizeConditionsRoleEmployeeExclusive(tc);
        poolRuleConditions[currentEditingRuleId] = tc;
        updatePoolRuleConditionDisplay(currentEditingRuleId);
      }
      closeDrawer('tipsDrawer');
      showNotification(tipTerm('小费取值条件保存成功'));
    }

