    function collectFormData() {
      var ruleName = document.getElementById('ruleName').value.trim();
      var storeSel = document.getElementById('storeSelect');
      var store = storeSel.value || '';
      var poolRules = [];
      document.querySelectorAll('.pool-rule-card').forEach(function(card) {
        var ruleId = card.dataset.ruleId;
        var type = card.dataset.ruleType || parsePoolRuleType(ruleId);
        if (!ruleId) return;
        if (type === 'custom') {
          var amtInp = card.querySelector('input.pool-custom-amount');
          var pctInp = card.querySelector('input.pool-custom-pct');
          var nameInp = card.querySelector('.pool-rule-name');
          var amount = amtInp ? (parseFloat(amtInp.value) || 0) : 0;
          var pct = pctInp ? (parseFloat(pctInp.value) || 100) : 100;
          var name = (nameInp && nameInp.value && nameInp.value.trim()) || getPoolRuleBaseNames().custom;
          poolRules.push({ type: type, id: ruleId, name: name, amount: amount, pct: pct });
        } else {
          var nameInp = card.querySelector('.pool-rule-name');
          var inp = card.querySelector('input[type="number"]:not(.pool-custom-amount):not(.pool-custom-pct)');
          var pct = inp ? (parseFloat(inp.value) || 0) : 0;
          var baseNames = getPoolRuleBaseNames();
          var name = (nameInp && nameInp.value && nameInp.value.trim()) || (ruleId.indexOf('_') >= 0 ? baseNames[type] + ruleId.slice(String(type).length + 1) : baseNames[type]);
          var pr = { type: type, id: ruleId, name: name, pct: pct };
          if (poolRuleConditions[ruleId]) pr.conditions = poolRuleConditions[ruleId];
          poolRules.push(pr);
        }
      });
      var deductData = collectDeductRuleData();
      var deductRoles = deductData.deductRoles;
      var deductEmployees = deductData.deductEmployees;
      var receivers = [];
      document.querySelectorAll('#receiverTableBody tr.receiver-primary-row').forEach(function(tr) {
        var ms = tr.querySelector('.receiver-role-select');
        if (!ms) return;
        var roles = [];
        ms.querySelectorAll('input[type="checkbox"]:checked').forEach(function(cb) { roles.push(cb.value); });
        var pctInp = tr.querySelector('input[type="number"]');
        var pct = pctInp ? (parseFloat(pctInp.value) || 0) : 0;
        var employeeWeights = {};
        try {
          if (tr.dataset.employeeWeights) employeeWeights = JSON.parse(tr.dataset.employeeWeights);
        } catch (e) {}
        var subReceivers = [];
        var block = getReceiverSecondaryBlock(tr);
        if (block) {
          var stbody = block.querySelector('.receiver-sub-tbody');
          if (stbody) {
            stbody.querySelectorAll('tr.receiver-sub-row').forEach(function(sr) {
              var sms = sr.querySelector('.receiver-sub-role-select');
              if (!sms) return;
              var sroles = [];
              sms.querySelectorAll('input[type="checkbox"]:checked').forEach(function(cb) { sroles.push(cb.value); });
              var spctInp = sr.querySelector('input[type="number"]');
              var spct = spctInp ? (parseFloat(spctInp.value) || 0) : 0;
              var sew = {};
              try {
                if (sr.dataset.employeeWeights) sew = JSON.parse(sr.dataset.employeeWeights);
              } catch (e2) {}
              if (sroles.length > 0 && spct > 0) subReceivers.push({ roles: sroles, pct: spct, employeeWeights: sew });
            });
          }
        }
        var rec = { roles: roles, pct: pct, employeeWeights: employeeWeights };
        if (subReceivers.length) rec.subReceivers = subReceivers;
        if (roles.length > 0 && pct > 0) receivers.push(rec);
      });
      var distRadio = document.querySelector('input[name="distribution"]:checked');
      var clockRadio = document.querySelector('input[name="clockin"]:checked');
      // Compatibility summaries must come from pool cards, never from a contributor drawer's current DOM.
      var salesConditions = JSON.parse(JSON.stringify(((poolRules.find(function(p) { return p.type === 'sales' || p.type === 'personal_sales'; }) || {}).conditions) || {}));
      var tipsConditions = JSON.parse(JSON.stringify(((poolRules.find(function(p) { return p.type === 'tips'; }) || {}).conditions) || {}));
      var surchargeConditions = JSON.parse(JSON.stringify(((poolRules.find(function(p) { return p.type === 'surcharge'; }) || {}).conditions) || {}));
      var allocationMode = (document.querySelector('input[name="allocationMode"]:checked') || {}).value || 'legacy_pool';
      var data = {
        ruleName: ruleName,
        store: store,
        poolRules: poolRules,
        deductRoles: deductRoles,
        deductEmployees: deductEmployees,
        contributionMode: contributionMode,
        deductConfig: deductData.deductConfig,
        receivers: receivers,
        distribution: distRadio ? distRadio.value : 'average',
        clockin: clockRadio ? clockRadio.value : 'clock',
        shiftWorkHours:shiftScopeDraft?collectShiftWorkHours():null,
        allocationScope: shiftScopeDraft && clockRadio && clockRadio.value==='time_window' ? 'shift' : clockRadio && clockRadio.value==='time_window' ? 'time_window' : 'day',
        salesConditions: salesConditions,
        tipsConditions: tipsConditions,
        surchargeConditions: surchargeConditions,
        allocationMode: allocationMode,
        poolKind: currentPoolKind
      };
      var workHoursConfig = collectWorkHoursConfig();
      if (workHoursConfig) data.workHoursConfig = workHoursConfig;
      if (allocationMode === 'order_tip_then_residual') {
        data.tipClaims = collectTipClaims();
        data.residual = { receivers: collectOrderResidualReceivers() };
        data.deductRoles = [];
        data.deductEmployees = null;
        data.deductConfig = {};
        data.receivers = [];
        delete data.salesConditions;
        delete data.tipsConditions;
        delete data.surchargeConditions;
      }
      if(typeof applyPoolSalesDeductionData==='function')applyPoolSalesDeductionData(data);
      return data;
    }

    function submitRule() {
      var attendanceChoice = document.querySelector('input[name="clockin"]:checked');
      if (!attendanceChoice || ['clock', 'unrestricted', 'time_window'].indexOf(attendanceChoice.value) < 0) {
        showNotification('请选择接收员工打卡要求后保存', 'warning');
        return;
      }
      var ruleName = document.getElementById('ruleName').value.trim();
      if (!ruleName) {
        showNotification('请输入规则名称', 'error');
        return;
      }
      var storeSel = document.getElementById('storeSelect');
      var store = storeSel.value || '';
      if (!store) {
        showNotification('请选择门店', 'error');
        return;
      }
      if(typeof validatePoolSalesDeductions==='function'&&!validatePoolSalesDeductions())return;
      if (!validateWorkHoursConfig()) return;
      if (contributionMode !== 'merchant' && typeof validateContributorSharesBeforeSave === 'function' && !validateContributorSharesBeforeSave()) return;
      var allocMode = (document.querySelector('input[name="allocationMode"]:checked') || {}).value || 'legacy_pool';
      if (allocMode === 'legacy_pool') {
        if (document.querySelectorAll('.pool-rule-card').length === 0) {
          showNotification(tipTerm('请至少添加一项小费池金额计算规则'), 'error');
          return;
        }
        var receivers = document.querySelectorAll('#receiverTableBody tr.receiver-primary-row');
        var hasReceiver = false;
        receivers.forEach(function(tr) {
          var ms = tr.querySelector('.receiver-role-select');
          var pctInp = tr.querySelector('input[type="number"]');
          var pct = pctInp ? (parseFloat(pctInp.value) || 0) : 0;
          if (ms && ms.querySelectorAll('input[type="checkbox"]:checked').length > 0 && pct > 0) hasReceiver = true;
        });
        if (!hasReceiver) {
          showNotification(tipTerm('请至少添加一条小费池接收方规则（角色、占比均需填写）'), 'error');
          return;
        }
        var condErr = null;
        document.querySelectorAll('.pool-rule-card[data-rule-id]').forEach(function(card) {
          var ruleId = card.dataset.ruleId;
          var type = card.dataset.ruleType || parsePoolRuleType(ruleId);
          if ((isSalesLikePoolType(type) || type === 'tips' || type === 'surcharge' || type === 'manual') && !hasValidConditions(ruleId)) {
            var nameInp = card.querySelector('.pool-rule-name');
            var baseNames = getPoolRuleBaseNames();
            var name = (nameInp && nameInp.value && nameInp.value.trim()) || (ruleId.indexOf('_') >= 0 ? baseNames[type] + ruleId.slice(String(type).length + 1) : baseNames[type]);
            condErr = condErr || name;
          }
        });
        if (condErr) {
          showNotification('请为「' + condErr + '」设置取值条件（必填）', 'error');
          return;
        }
        if (!isSurchargePoolKind() && !contributionMode) { showNotification('请选择贡献方式', 'error'); return; }
        if (!isSurchargePoolKind() && contributionMode === 'employees' && !document.querySelector('#deductRulesContainer .deduct-basis-card') && !Object.keys(poolSalesDeductions).some(function(id){return poolSalesDeductions[id].role;})) { showNotification('请至少添加一条员工贡献规则', 'error'); return; }
        var deductCondErr = null;
        var deductRateErr = null;
        document.querySelectorAll('#deductRulesContainer .deduct-basis-card').forEach(function(card) {
          if (contributionMode === 'merchant' || deductCondErr || deductRateErr) return;
          var cardId = card.dataset.deductId;
          var basis = card.dataset.basis || parseDeductCardBasis(cardId);
          if (!isDeductRatePctValid(cardId)) {
            deductRateErr = DEDUCT_BASIS_LABELS[basis] || basis;
            return;
          }
          var entry = collectDeductScopeEntry(cardId);
          if (!entry || !hasContributorScope({role:entry.roles,employee:entry.employee})) {
            deductCondErr = DEDUCT_BASIS_LABELS[basis] || basis;
            return;
          }
        });
        if (deductRateErr) {
          showNotification('请为扣除方「' + deductRateErr + '」填写大于 0 的占比（必填）', 'error');
          return;
        }
        if (deductCondErr) {
          showNotification('请为扣除方「' + deductCondErr + '」设置取值条件（角色或员工必须选择一项）', 'error');
          return;
        }
      } else {
        var tclaims = collectTipClaims();
        if (!tclaims.length) {
          showNotification(tipTerm('请至少添加一条计提小费接受方规则'), 'error');
          return;
        }
        var claimBad = false;
        tclaims.forEach(function(c) {
          if (c.pct <= 0 || !c.receiverRoles || !c.receiverRoles.length) claimBad = true;
        });
        if (claimBad) {
          showNotification(tipTerm('每条计提小费接受方规则须填写大于 0 的计提比例，并在接收角色中至少选择一名角色'), 'error');
          return;
        }
        var hasResResidual = false;
        document.querySelectorAll('#orderResidualReceiverTableBody tr.order-residual-primary-row').forEach(function(tr) {
          var ms = tr.querySelector('.receiver-role-select');
          var pctInp = tr.querySelector('input[type="number"]');
          var pct = pctInp ? (parseFloat(pctInp.value) || 0) : 0;
          if (ms && ms.querySelectorAll('input[type="checkbox"]:checked').length > 0 && pct > 0) hasResResidual = true;
        });
        if (!hasResResidual) {
          showNotification(tipTerm('请至少添加一条剩余小费接收方规则（角色、占比均需填写）'), 'error');
          return;
        }
        if (document.querySelectorAll('.pool-rule-card').length === 0) {
          showNotification(tipTerm('请至少添加一项小费池金额计算规则'), 'error');
          return;
        }
        var condErrOt = null;
        document.querySelectorAll('.pool-rule-card[data-rule-id]').forEach(function(card) {
          var ruleId = card.dataset.ruleId;
          var type = card.dataset.ruleType || parsePoolRuleType(ruleId);
          if ((isSalesLikePoolType(type) || type === 'tips' || type === 'surcharge' || type === 'manual') && !hasValidConditions(ruleId)) {
            var nameInp = card.querySelector('.pool-rule-name');
            var baseNames = getPoolRuleBaseNames();
            var name = (nameInp && nameInp.value && nameInp.value.trim()) || (ruleId.indexOf('_') >= 0 ? baseNames[type] + ruleId.slice(String(type).length + 1) : baseNames[type]);
            condErrOt = condErrOt || name;
          }
        });
        if (condErrOt) {
          showNotification('请为「' + condErrOt + '」设置取值条件（必填）', 'error');
          return;
        }
      }
      var data = collectFormData();
      if(data.allocationScope==='shift'){try{data.shiftWorkHours=window.TipOutTimeWindow.validateShiftWorkHours(data.shiftWorkHours,data.distribution);}catch(error){showNotification(error.message,'error');return;}}
      if (data.allocationMode !== 'order_tip_then_residual') {
        try { window.TipOutEmployeeWeights.groups(data.receivers); }
        catch (error) { showNotification(error.message, 'error'); return; }
      }
      if (data.clockin === 'time_window') {
        if (data.allocationMode !== 'legacy_pool' || data.poolKind !== 'tip') {
          showNotification('按打卡时段统计并分配小费目前仅支持普通小费池规则', 'error');
          return;
        }
        var unsupportedTimeRule = (data.poolRules || []).find(function(item) {
          var conditions = item.conditions || {};
          return ['tips', 'sales', 'personal_sales', 'manual'].indexOf(item.type) < 0 ||
            !!conditions.containsProduct || !!conditions.menu || !!conditions.surchargeType || !!conditions.types ||
            !!(conditions.shift && conditions.shift.length);
        });
        if (unsupportedTimeRule) {
          showNotification('按时段参与暂不支持所选的小费池来源或筛选条件，请调整后保存', 'error');
          return;
        }
      }
      if (data.allocationMode !== 'order_tip_then_residual' && window.TipOutRosterDirectory && TipOutRosterDirectory.validateRuleReferences) {
        var referenceIssues = TipOutRosterDirectory.validateRuleReferences({
          store: data.store,
          receivers: data.receivers
        }, data.store);
        if (referenceIssues.length) {
          showNotification('接收方包含失效或无可用员工的角色，请先在「角色与员工」中修正后再保存', 'error');
          return;
        }
      }
      var params = getEditParams();
      var rules = ruleData.getRules();
      var rule;
      if (params.mode === 'edit' && params.id) {
        rule = rules.filter(function(r) { return r.id === parseInt(params.id, 10); })[0];
        if (rule) {
          rule.ruleName = data.ruleName;
          rule.store = data.store;
          rule.distribution = data.distribution;
          rule.clockin = data.clockin;
          rule.allocationScope=data.allocationScope;delete rule.shifts;
          if(data.shiftWorkHours)rule.shiftWorkHours=data.shiftWorkHours;else delete rule.shiftWorkHours;
          if (data.workHoursConfig) rule.workHoursConfig = data.workHoursConfig;
          else delete rule.workHoursConfig;
          rule.allocationMode = data.allocationMode || 'legacy_pool';
          rule.poolKind = data.poolKind || 'tip';
          if (rule.allocationMode === 'order_tip_then_residual') {
            rule.poolRules = data.poolRules;
            rule.tipClaims = data.tipClaims;
            rule.residual = data.residual;
            rule.deductRoles = [];
            rule.deductEmployees = null;
            rule.deductConfig = {};
            rule.receivers = [];
            delete rule.orderTipSource;
            delete rule.salesConditions;
            delete rule.tipsConditions;
            delete rule.surchargeConditions;
          } else {
            rule.poolRules = data.poolRules;
            rule.deductRoles = data.deductRoles;
            rule.deductEmployees = data.deductEmployees || null;
            rule.deductConfig = data.deductConfig || {};
          rule.contributionMode = data.contributionMode;
            rule.receivers = data.receivers;
            rule.salesConditions = data.salesConditions || {};
            rule.tipsConditions = data.tipsConditions || {};
            rule.surchargeConditions = data.surchargeConditions || {};
            delete rule.orderTipSource;
            delete rule.tipClaims;
            delete rule.residual;
          }
          ruleData.saveRules(rules);
        }
      } else {
        rule = {
          id: ruleData.getNextRuleId(),
          ruleName: data.ruleName,
          store: data.store,
          distribution: data.distribution,
          clockin: data.clockin,
          allocationScope:data.allocationScope,
          allocationMode: data.allocationMode || 'legacy_pool',
          poolKind: data.poolKind || 'tip'
        };
        if(data.shiftWorkHours)rule.shiftWorkHours=data.shiftWorkHours;else delete rule.shiftWorkHours;
          if (data.workHoursConfig) rule.workHoursConfig = data.workHoursConfig;
        if (rule.allocationMode === 'order_tip_then_residual') {
          rule.poolRules = data.poolRules;
          rule.tipClaims = data.tipClaims;
          rule.residual = data.residual;
          rule.deductRoles = [];
          rule.deductEmployees = null;
          rule.deductConfig = {};
          rule.receivers = [];
        } else {
          rule.poolRules = data.poolRules;
          rule.deductRoles = data.deductRoles;
          rule.deductEmployees = data.deductEmployees || null;
          rule.deductConfig = data.deductConfig || {};
          rule.contributionMode = data.contributionMode;
          rule.receivers = data.receivers;
          rule.salesConditions = data.salesConditions || {};
          rule.tipsConditions = data.tipsConditions || {};
          rule.surchargeConditions = data.surchargeConditions || {};
        }
        rules.push(rule);
        ruleData.saveRules(rules);
      }
      showNotification('规则保存成功', 'success');
      setTimeout(function() { window.location.href = 'rules.html'; }, 1500);
    }

